using System.Collections.Generic;
using UnityEditor;
using UnityEditor.Animations;
using UnityEngine;
using UnityEngine.UI;

// Level 7 "Kraken's Throne" part of Build All: imports the Blender models from 3d/level7
// (generated by Tools/Blender/build_kraken.py), splits the rigged clips, creates the
// AnimatorControllers, materials, prefabs, the encounter hierarchy and its HUD pieces.
public static partial class GameSetup
{
    const string KrakenDir        = "Assets/Models/Kraken/";
    const string KrakenAnimDir    = "Assets/Animations/Kraken/";
    const string KrakenConfigPath = "Assets/Config/KrakenLevelConfig.asset";

    static readonly string[] KrakenStaticModels =
        { "KrakenBody", "KrakenThrone", "KrakenKing", "KrakenWhirlpool", "Sunfish", "Jellyfish", "KrakenRock", "InkBlob" };
    static readonly string[] KrakenRiggedModels = { "KrakenTentacle", "Dolphin" };

    [System.Serializable] class KrakenClipInfo { public string name; public int first; public int last; public bool loop; }
    [System.Serializable] class KrakenClipMeta { public float slamReach; public float slamImpactTime; public float throwReleaseTime; public float length; public string tipBone; public float height; }
    [System.Serializable] class KrakenClipFile { public int fps; public KrakenClipInfo[] clips; public KrakenClipMeta meta; }

    static string Level7SourceDir => System.IO.Path.Combine(System.IO.Path.GetDirectoryName(Application.dataPath), "3d", "level7");

    static KrakenClipFile LoadKrakenClips(string model)
    {
        string path = System.IO.Path.Combine(Level7SourceDir, model + ".clips.json");
        if (!System.IO.File.Exists(path)) { Debug.LogWarning("[ShipButtlr] Clip file missing: " + path); return null; }
        return JsonUtility.FromJson<KrakenClipFile>(System.IO.File.ReadAllText(path));
    }

    // -------------------------------------------------------------------------
    // Import (called from CopyModels)
    // -------------------------------------------------------------------------

    static void ImportKrakenModels()
    {
        EnsureFolder("Assets/Models", "Kraken");
        string dir = Level7SourceDir;
        if (!System.IO.Directory.Exists(dir))
        {
            Debug.LogWarning("[ShipButtlr] 3d/level7 missing — run Tools/Blender/build_kraken.py in Blender, then Build All again.");
            return;
        }
        foreach (string n in KrakenStaticModels)
            ImportModel(System.IO.Path.Combine(dir, n + ".fbx"), KrakenDir + n + ".fbx", bakeAxis: true);
        foreach (string n in KrakenRiggedModels)
            ImportRiggedModel(System.IO.Path.Combine(dir, n + ".fbx"), KrakenDir + n + ".fbx", LoadKrakenClips(n));
    }

    static void ImportRiggedModel(string srcPath, string assetPath, KrakenClipFile clips)
    {
        if (!System.IO.File.Exists(srcPath)) { Debug.LogWarning("[ShipButtlr] Model not found at: " + srcPath); return; }
        string projectRoot = System.IO.Path.GetDirectoryName(Application.dataPath);
        System.IO.File.Copy(srcPath, System.IO.Path.Combine(projectRoot, assetPath), overwrite: true);
        AssetDatabase.Refresh();
        var importer = AssetImporter.GetAtPath(assetPath) as ModelImporter;
        if (importer == null) return;
        importer.materialImportMode = ModelImporterMaterialImportMode.ImportViaMaterialDescription;
        importer.materialLocation   = ModelImporterMaterialLocation.External;
        importer.bakeAxisConversion = true;
        importer.useFileScale       = true;
        importer.globalScale        = 1f;
        importer.animationType      = ModelImporterAnimationType.Generic;
        importer.avatarSetup        = ModelImporterAvatarSetup.CreateFromThisModel;
        importer.importAnimation    = true;
        importer.animationCompression = ModelImporterAnimationCompression.KeyframeReduction;
        importer.clipAnimations     = new ModelImporterClipAnimation[0];
        AssetDatabase.ImportAsset(assetPath, ImportAssetOptions.ForceUpdate);

        importer = AssetImporter.GetAtPath(assetPath) as ModelImporter;
        var takes = importer.importedTakeInfos;
        if (takes == null || takes.Length == 0 || clips == null || clips.clips == null)
        {
            Debug.LogError("[ShipButtlr] " + assetPath + ": no animation take or clip file — clips not split.");
            return;
        }
        var take = takes[0];
        Debug.Log($"[ShipButtlr] {assetPath}: take '{take.name}' {take.startTime:F3}–{take.stopTime:F3} s @ {take.sampleRate} fps");
        var list = new List<ModelImporterClipAnimation>();
        foreach (var c in clips.clips)
        {
            list.Add(new ModelImporterClipAnimation
            {
                name       = c.name,
                takeName   = take.name,
                firstFrame = c.first,
                lastFrame  = c.last,
                loopTime   = c.loop,
                loop       = c.loop,
                wrapMode   = c.loop ? WrapMode.Loop : WrapMode.ClampForever,
            });
        }
        importer.clipAnimations = list.ToArray();
        importer.SaveAndReimport();
        Debug.Log($"[ShipButtlr] {assetPath}: {list.Count} clips split");
    }

    // -------------------------------------------------------------------------
    // Materials (called from CreateMaterials)
    // -------------------------------------------------------------------------

    static void AddKrakenMaterials(Dictionary<string, Material> dict)
    {
        // Keys match the Blender material slot names (Tools/Blender/build_kraken.py).
        // Emission is enabled (black) on everything HitFlash / the jellyfish highlight may light up.
        dict["L7_KrakenSkin"]   = Emissive(MakeMat("L7_KrakenSkin",   new Color(0.45f, 0.10f, 0.22f), smoothness: 0.45f));
        dict["L7_KrakenBelly"]  = Emissive(MakeMat("L7_KrakenBelly",  new Color(0.88f, 0.50f, 0.48f), smoothness: 0.35f));
        dict["L7_Eye"]          = Emissive(MakeMat("L7_Eye",          new Color(1.00f, 0.82f, 0.10f), smoothness: 0.8f));
        dict["L7_Pupil"]        = Emissive(MakeMat("L7_Pupil",        new Color(0.03f, 0.03f, 0.03f), smoothness: 0.9f));
        dict["L7_Gold"]         = Emissive(MakeMat("L7_Gold",         new Color(0.95f, 0.72f, 0.15f), smoothness: 0.6f, metallic: 0.8f));
        dict["L7_Gem"]          = Emissive(MakeMat("L7_Gem",          new Color(0.10f, 0.80f, 0.75f), smoothness: 0.9f));
        dict["L7_ThroneRock"]   = Emissive(MakeMat("L7_ThroneRock",   new Color(0.30f, 0.33f, 0.36f)));
        dict["L7_Coral"]        = Emissive(MakeMat("L7_Coral",        new Color(0.95f, 0.45f, 0.40f)));
        dict["L7_Seaweed"]      = Emissive(MakeMat("L7_Seaweed",      new Color(0.15f, 0.45f, 0.25f)));
        dict["L7_SunfishSkin"]  = Emissive(MakeMat("L7_SunfishSkin",  new Color(0.60f, 0.65f, 0.70f), smoothness: 0.3f));
        dict["L7_SunfishBelly"] = Emissive(MakeMat("L7_SunfishBelly", new Color(0.88f, 0.89f, 0.86f), smoothness: 0.3f));
        dict["L7_JellyGlow"]    = Emissive(MakeMat("L7_JellyGlow",    new Color(1.00f, 0.75f, 1.00f), smoothness: 0.7f));
        dict["L7_Rock"]         = MakeMat("L7_Rock",         new Color(0.42f, 0.38f, 0.34f));
        dict["L7_Ink"]          = MakeMat("L7_Ink",          new Color(0.05f, 0.03f, 0.10f), smoothness: 0.9f);
        dict["L7_DolphinSkin"]  = MakeMat("L7_DolphinSkin",  new Color(0.40f, 0.55f, 0.70f), smoothness: 0.7f);
        dict["L7_DolphinBelly"] = MakeMat("L7_DolphinBelly", new Color(0.85f, 0.90f, 0.95f), smoothness: 0.6f);

        dict["L7_JellyBell"]  = Emissive(MakeTransparentMat("L7_JellyBell",  new Color(0.85f, 0.45f, 0.95f, 0.78f), smoothness: 0.8f));
        dict["L7_Shield"]     = MakeTransparentMat("L7_Shield",     new Color(0.35f, 0.85f, 1f, 0.28f), smoothness: 0.55f);
        dict["L7_DangerZone"] = MakeTransparentMat("L7_DangerZone", new Color(1f, 0.15f, 0.12f, 0.35f));
        dict["L7_JellyRing"]  = MakeTransparentMat("L7_JellyRing",  new Color(1f, 0.45f, 1f, 0.35f));
        var ring = MakeTransparentMat("L7_ArenaRing", new Color(0.75f, 0.95f, 1f, 0.55f));
        Emissive(ring, new Color(0.4f, 0.8f, 1f) * 1.2f);
        dict["L7_ArenaRing"] = ring;

        // Whirlpool: custom animated shader (Assets/Shaders/Whirlpool.shader), saved so it is never stripped
        string wpPath = "Assets/Materials/L7_Whirlpool.mat";
        if (AssetDatabase.LoadAssetAtPath<Material>(wpPath) != null) AssetDatabase.DeleteAsset(wpPath);
        var wpShader = Shader.Find("ShipButtlr/Whirlpool");
        if (wpShader == null)
        {
            Debug.LogError("[ShipButtlr] ShipButtlr/Whirlpool shader not found — using a transparent Lit fallback.");
            dict["L7_Whirlpool"] = MakeTransparentMat("L7_Whirlpool", new Color(0.10f, 0.35f, 0.60f, 0.8f));
        }
        else
        {
            var wp = new Material(wpShader);
            AssetDatabase.CreateAsset(wp, wpPath);
            dict["L7_Whirlpool"] = wp;
        }
    }

    static Material Emissive(Material m) => Emissive(m, Color.black);

    static Material Emissive(Material m, Color emission)
    {
        m.EnableKeyword("_EMISSION");
        m.SetColor("_EmissionColor", emission);
        m.globalIlluminationFlags = MaterialGlobalIlluminationFlags.RealtimeEmissive;
        EditorUtility.SetDirty(m);
        return m;
    }

    static Material MakeTransparentMat(string assetName, Color color, float smoothness = 0f)
    {
        var mat = MakeMat(assetName, color, smoothness);
        mat.SetFloat("_Surface", 1f);
        mat.SetFloat("_Blend", 0f);
        mat.SetFloat("_SrcBlend", (float)UnityEngine.Rendering.BlendMode.SrcAlpha);
        mat.SetFloat("_DstBlend", (float)UnityEngine.Rendering.BlendMode.OneMinusSrcAlpha);
        mat.SetFloat("_ZWrite", 0f);
        mat.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");
        mat.SetOverrideTag("RenderType", "Transparent");
        mat.renderQueue = 3000;
        EditorUtility.SetDirty(mat);
        return mat;
    }

    // -------------------------------------------------------------------------
    // Config asset
    // -------------------------------------------------------------------------

    static KrakenLevelConfig EnsureKrakenConfig(GameObject playerShip)
    {
        EnsureFolder("Assets", "Config");
        var cfg = AssetDatabase.LoadAssetAtPath<KrakenLevelConfig>(KrakenConfigPath);
        bool created = false;
        if (cfg == null)
        {
            cfg = ScriptableObject.CreateInstance<KrakenLevelConfig>();
            AssetDatabase.CreateAsset(cfg, KrakenConfigPath);
            created = true;
        }
        float len = KrakenLevelConfig.MeasureShipLength(playerShip);
        if (len > 0f && !Mathf.Approximately(len, cfg.shipLength))
        {
            cfg.shipLength = len;
            EditorUtility.SetDirty(cfg);
        }
        Debug.Log($"[ShipButtlr] KrakenLevelConfig {(created ? "created" : "kept (your tuning is preserved)")}; shipLength = {cfg.shipLength} " +
                  $"→ arena r {cfg.ArenaRadius}, whirlpool r {cfg.WhirlpoolRadius} at {cfg.WhirlpoolCentreDist}, emergence r {cfg.EmergenceRadius:F1}");
        return cfg;
    }

    // -------------------------------------------------------------------------
    // Animator controllers
    // -------------------------------------------------------------------------

    static AnimatorController CreateKrakenAnimator(string fbxPath, string ctrlName, string defaultState)
    {
        EnsureFolder("Assets", "Animations");
        EnsureFolder("Assets/Animations", "Kraken");
        string path = KrakenAnimDir + ctrlName + ".controller";
        if (AssetDatabase.LoadAssetAtPath<Object>(path) != null) AssetDatabase.DeleteAsset(path);
        var ctrl = AnimatorController.CreateAnimatorControllerAtPath(path);
        var sm = ctrl.layers[0].stateMachine;
        int count = 0;
        foreach (var o in AssetDatabase.LoadAllAssetsAtPath(fbxPath))
        {
            if (!(o is AnimationClip clip) || clip.name.StartsWith("__preview__")) continue;
            var st = sm.AddState(clip.name);
            st.motion = clip;
            if (clip.name == defaultState) sm.defaultState = st;
            count++;
        }
        Debug.Log($"[ShipButtlr] {path}: {count} states (default {defaultState})");
        if (count == 0) Debug.LogError("[ShipButtlr] " + fbxPath + " has no clips — Animator will be empty.");
        return ctrl;
    }

    static AnimationClip KrakenClip(string fbxPath, string name)
    {
        foreach (var o in AssetDatabase.LoadAllAssetsAtPath(fbxPath))
            if (o is AnimationClip clip && clip.name == name) return clip;
        return null;
    }

    static Transform FindDeep(Transform t, string name)
    {
        if (t.name == name) return t;
        for (int i = 0; i < t.childCount; i++)
        {
            var r = FindDeep(t.GetChild(i), name);
            if (r != null) return r;
        }
        return null;
    }

    // Centroid (world) of all triangles drawn with the given material
    static bool MaterialCentroid(GameObject go, Material mat, out Vector3 centre)
    {
        centre = Vector3.zero; int n = 0;
        foreach (var r in go.GetComponentsInChildren<Renderer>(true))
        {
            Mesh mesh = null;
            Transform tr = r.transform;
            if (r is SkinnedMeshRenderer smr) mesh = smr.sharedMesh;
            else { var mf = r.GetComponent<MeshFilter>(); if (mf != null) mesh = mf.sharedMesh; }
            if (mesh == null) continue;
            var sm = r.sharedMaterials;
            var verts = mesh.vertices;
            for (int i = 0; i < sm.Length && i < mesh.subMeshCount; i++)
            {
                if (sm[i] != mat) continue;
                foreach (int vi in mesh.GetTriangles(i)) { centre += tr.TransformPoint(verts[vi]); n++; }
            }
        }
        if (n > 0) centre /= n;
        return n > 0;
    }

    // Turns visual 180° about Y when the marker material's centroid is on the -Z side of anchor
    static void FaceForward(string label, GameObject visual, Transform anchor, Material marker, float minZ)
    {
        if (!MaterialCentroid(visual, marker, out Vector3 c))
        {
            CheckOrientation(label, false, "marker material not found on the model");
            return;
        }
        Vector3 local = anchor.InverseTransformPoint(c);
        if (local.z < 0f)
        {
            visual.transform.localRotation = Quaternion.Euler(0f, 180f, 0f) * visual.transform.localRotation;
            MaterialCentroid(visual, marker, out c);
            local = anchor.InverseTransformPoint(c);
        }
        CheckOrientation(label, local.z > minZ, $"{marker.name} centroid local={local}");
    }

    // -------------------------------------------------------------------------
    // Prefabs
    // -------------------------------------------------------------------------

    static GameObject CreateKrakenDangerZonePrefab(Material mat)
    {
        var root = new GameObject("KrakenDangerZone");
        var dz = root.AddComponent<DangerZone>();
        dz.outer = MakeDisc("Outer", root.transform, mat, 0f).GetComponent<Renderer>();
        dz.inner = MakeDisc("Inner", root.transform, mat, 0.015f).GetComponent<Renderer>();
        var prefab = SavePrefab(root, "Assets/Prefabs/KrakenDangerZone.prefab");
        Object.DestroyImmediate(root);
        return prefab;
    }

    static GameObject MakeDisc(string name, Transform parent, Material mat, float y)
    {
        var go = GameObject.CreatePrimitive(PrimitiveType.Cylinder);
        go.name = name;
        go.transform.SetParent(parent, false);
        go.transform.localPosition = new Vector3(0f, y, 0f);
        go.transform.localScale = new Vector3(1f, 0.02f, 1f);
        Object.DestroyImmediate(go.GetComponent<Collider>());
        var mr = go.GetComponent<MeshRenderer>();
        mr.sharedMaterial = mat;
        mr.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
        mr.receiveShadows = false;
        return go;
    }

    static GameObject CreateArcPrefab(string name, string model, ArcProjectile.Kind kind, float spin, float scale,
                                      Dictionary<string, Material> mats)
    {
        var src = AssetDatabase.LoadAssetAtPath<GameObject>(KrakenDir + model + ".fbx");
        var root = new GameObject(name);
        var ap = root.AddComponent<ArcProjectile>();
        ap.kind = kind;
        ap.spinSpeed = spin;
        if (src != null)
        {
            var vis = PlaceModel(src, root.transform, Vector3.zero, Quaternion.identity, "Model", mats);
            vis.transform.localScale = Vector3.one * scale;
            foreach (var r in vis.GetComponentsInChildren<Renderer>()) r.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
        }
        else
        {
            var s = GameObject.CreatePrimitive(PrimitiveType.Sphere);
            Object.DestroyImmediate(s.GetComponent<Collider>());
            s.transform.SetParent(root.transform, false);
            s.transform.localScale = Vector3.one * scale * 2f;
            s.GetComponent<MeshRenderer>().sharedMaterial = mats[kind == ArcProjectile.Kind.Ink ? "L7_Ink" : "L7_Rock"];
        }
        var prefab = SavePrefab(root, "Assets/Prefabs/" + name + ".prefab");
        Object.DestroyImmediate(root);
        return prefab;
    }

    // Phase 2 arena-wall rock: IslandData (ship collision + L5+ crash damage) + capsule (torpedoes explode)
    static GameObject CreateEdgeRockPrefab(Dictionary<string, Material> mats, float radius)
    {
        var src = AssetDatabase.LoadAssetAtPath<GameObject>(KrakenDir + "KrakenRock.fbx");
        var root = new GameObject("KrakenEdgeRock");
        root.AddComponent<IslandData>().radius = radius;
        var cap = root.AddComponent<CapsuleCollider>();
        cap.radius = radius * 0.85f; cap.height = 16f; cap.center = new Vector3(0f, 2f, 0f); cap.direction = 1;
        if (src != null)
        {
            var vis = PlaceModel(src, root.transform, new Vector3(0f, -2f, 0f), Quaternion.identity, "Model", mats);
            float s = radius / 1.5f;                       // KrakenRock radius ~1.5
            vis.transform.localScale = new Vector3(s, s * 2.8f, s);   // tall enough to read as a wall from the ship camera
            foreach (var r in vis.GetComponentsInChildren<Renderer>())
                r.sharedMaterial = mats["L7_ThroneRock"];
        }
        var prefab = SavePrefab(root, "Assets/Prefabs/KrakenEdgeRock.prefab");
        Object.DestroyImmediate(root);
        return prefab;
    }

    static GameObject CreateJellyfishPrefab(Dictionary<string, Material> mats)
    {
        var src = AssetDatabase.LoadAssetAtPath<GameObject>(KrakenDir + "Jellyfish.fbx");
        var root = new GameObject("Jellyfish");
        var rb = root.AddComponent<Rigidbody>();
        rb.isKinematic = true; rb.useGravity = false;
        var jf = root.AddComponent<Jellyfish>();
        var pivot = new GameObject("Pivot").transform;
        pivot.SetParent(root.transform, false);
        jf.pivot = pivot;
        if (src != null)
        {
            var vis = PlaceModel(src, pivot, Vector3.zero, Quaternion.identity, "Model", mats);
            vis.transform.localScale = Vector3.one * 1.25f;
            jf.bodyRenderers = vis.GetComponentsInChildren<Renderer>();
        }
        var hit = new GameObject("Hitbox");
        hit.transform.SetParent(pivot, false);
        hit.transform.localPosition = new Vector3(0f, 1.2f, 0f);
        jf.hitbox = hit.AddComponent<SphereCollider>();
        jf.hitbox.radius = 1.8f;
        var ring = MakeDisc("HighlightRing", root.transform, mats["L7_JellyRing"], 0.07f);
        jf.highlightRing = ring.GetComponent<Renderer>();
        var prefab = SavePrefab(root, "Assets/Prefabs/Jellyfish.prefab");
        Object.DestroyImmediate(root);
        return prefab;
    }

    // -------------------------------------------------------------------------
    // Scene: the encounter
    // -------------------------------------------------------------------------

    static Transform NewChild(Transform parent, string name, Vector3 localPos)
    {
        var t = new GameObject(name).transform;
        t.SetParent(parent, false);
        t.localPosition = localPos;
        return t;
    }

    static CapsuleCollider AddCapsule(Transform parent, string name, Vector3 centre, float radius, float height)
    {
        var t = NewChild(parent, name, Vector3.zero);
        var c = t.gameObject.AddComponent<CapsuleCollider>();
        c.center = centre; c.radius = radius; c.height = height; c.direction = 1;
        return c;
    }

    static void KinematicBody(GameObject go)
    {
        var rb = go.AddComponent<Rigidbody>();
        rb.isKinematic = true;
        rb.useGravity  = false;
    }

    static BossEncounterController BuildKrakensThrone(Dictionary<string, Material> mats, GameObject root, GameObject playerShip,
                                                      GameObject splashPrefab, GameObject explosionPrefab)
    {
        var cfg = EnsureKrakenConfig(playerShip);
        var ctrl = root.AddComponent<BossEncounterController>();
        ctrl.config            = cfg;
        ctrl.splashPrefab      = splashPrefab;
        ctrl.explosionPrefab   = explosionPrefab;
        ctrl.arenaRingMaterial = mats["L7_ArenaRing"];
        ctrl.dangerZonePrefab  = CreateKrakenDangerZonePrefab(mats["L7_DangerZone"]);
        ctrl.inkPrefab         = CreateArcPrefab("InkProjectile", "InkBlob", ArcProjectile.Kind.Ink, 0f, 1.3f, mats);
        ctrl.rockPrefab        = CreateArcPrefab("KrakenRockProjectile", "KrakenRock", ArcProjectile.Kind.Rock, 260f, 1.2f, mats);
        ctrl.jellyfishPrefab   = CreateJellyfishPrefab(mats);
        ctrl.edgeRockPrefab    = CreateEdgeRockPrefab(mats, cfg.edgeRockRadius);

        // --- tentacles ---------------------------------------------------------
        string tentPath = KrakenDir + "KrakenTentacle.fbx";
        var tentModel   = AssetDatabase.LoadAssetAtPath<GameObject>(tentPath);
        var tentCtrl    = tentModel != null ? CreateKrakenAnimator(tentPath, "Tentacle", "Idle") : null;
        var tentMeta    = LoadKrakenClips("KrakenTentacle");
        float reach = tentMeta != null && tentMeta.meta != null && tentMeta.meta.slamReach > 0f ? tentMeta.meta.slamReach : 36f;
        float yawFix = MeasureTentacle(tentModel, tentPath, mats, ref reach);

        var tentList = new List<TentacleAttacker>();
        for (int i = 0; i < cfg.tentacleCount; i++)
        {
            float a = (i + 0.5f) * Mathf.PI * 2f / cfg.tentacleCount;
            var pos = new Vector3(Mathf.Sin(a), 0f, Mathf.Cos(a)) * cfg.TentacleRingRadius;
            var ta = BuildTentacle("Tentacle_" + i, root.transform, pos, tentModel, tentCtrl, tentMeta, mats, reach, yawFix, 1f);
            ta.pivot.localRotation = Quaternion.LookRotation(-pos.normalized);   // editor preview only (runtime re-aims)
            tentList.Add(ta);
        }
        ctrl.tentacles = tentList.ToArray();

        // --- whirlpool ---------------------------------------------------------
        var wpRoot = NewChild(root.transform, "Whirlpool", new Vector3(-55f, 0.15f, 25f));
        var wp = wpRoot.gameObject.AddComponent<Whirlpool>();
        wp.visual = NewChild(wpRoot, "Visual", Vector3.zero);
        var wpModel = AssetDatabase.LoadAssetAtPath<GameObject>(KrakenDir + "KrakenWhirlpool.fbx");
        if (wpModel != null)
        {
            var vis = PlaceModel(wpModel, wp.visual, Vector3.zero, Quaternion.identity, "Model", mats);
            wp.surface = vis.GetComponentInChildren<Renderer>();
            if (wp.surface != null)
            {
                wp.surface.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
                wp.modelRadius = Mathf.Max(1f, wp.surface.bounds.extents.x);
            }
            Debug.Log($"[ShipButtlr] Whirlpool model radius {wp.modelRadius:F2} (expect 30)");
        }
        ctrl.whirlpool = wp;

        // --- Phase 1 kraken ------------------------------------------------------
        var kRoot = NewChild(root.transform, "KrakenSurfaced", new Vector3(0f, 0f, 57f));
        kRoot.localRotation = Quaternion.Euler(0f, 180f, 0f);
        KinematicBody(kRoot.gameObject);
        var kr = kRoot.gameObject.AddComponent<SurfacedKraken>();
        kr.pivot = NewChild(kRoot, "Pivot", Vector3.zero);
        var bodyModel = AssetDatabase.LoadAssetAtPath<GameObject>(KrakenDir + "KrakenBody.fbx");
        if (bodyModel != null)
        {
            var vis = PlaceModel(bodyModel, kr.pivot, Vector3.zero, Quaternion.identity, "Model", mats);
            FaceForward("KrakenBody eyes toward +Z", vis, kRoot, mats["L7_Eye"], 6f);
            LogBounds(vis, "KrakenBody");
        }
        kr.hurtboxes = new Collider[] { AddCapsule(kr.pivot, "Hurtbox", new Vector3(0f, 0f, -1f), 13f, 64f) };
        kr.mouth = NewChild(kr.pivot, "Mouth", new Vector3(0f, 9f, 13.5f));
        kr.flash = kRoot.gameObject.AddComponent<HitFlash>();
        ctrl.kraken = kr;

        // --- sunfish -------------------------------------------------------------
        var sRoot = NewChild(root.transform, "Sunfish", new Vector3(18f, 0f, -12f));
        KinematicBody(sRoot.gameObject);
        var sf = sRoot.gameObject.AddComponent<Sunfish>();
        sf.pivot = NewChild(sRoot, "Pivot", new Vector3(0f, 2.6f, 0f));
        var sunModel = AssetDatabase.LoadAssetAtPath<GameObject>(KrakenDir + "Sunfish.fbx");
        if (sunModel != null)
        {
            var vis = PlaceModel(sunModel, sf.pivot, Vector3.zero, Quaternion.identity, "Model", mats);
            vis.transform.localScale = Vector3.one * 1.15f;
            FaceForward("Sunfish eyes toward +Z", vis, sRoot, mats["L7_Pupil"], 1f);
        }
        sf.hurtboxes = new Collider[] { AddCapsule(sf.pivot, "Hurtbox", Vector3.zero, 3.6f, 16f) };
        sf.flash = sRoot.gameObject.AddComponent<HitFlash>();
        ctrl.sunfish = sf;

        // --- throne kraken -------------------------------------------------------
        var tRoot = NewChild(root.transform, "KrakenThrone", Vector3.zero);
        tRoot.localRotation = Quaternion.Euler(0f, 180f, 0f);   // faces the player spawn (-Z)
        KinematicBody(tRoot.gameObject);
        var th = tRoot.gameObject.AddComponent<ThroneKraken>();
        th.pivot = NewChild(tRoot, "Pivot", Vector3.zero);
        var throneModel = AssetDatabase.LoadAssetAtPath<GameObject>(KrakenDir + "KrakenThrone.fbx");
        var kingModel   = AssetDatabase.LoadAssetAtPath<GameObject>(KrakenDir + "KrakenKing.fbx");
        GameObject throneVis = null, kingVis = null;
        if (throneModel != null) throneVis = PlaceModel(throneModel, th.pivot, Vector3.zero, Quaternion.identity, "ThroneModel", mats);
        if (kingModel   != null) kingVis   = PlaceModel(kingModel,   th.pivot, Vector3.zero, Quaternion.identity, "KingModel",   mats);
        if (kingVis != null)
        {
            Quaternion before = kingVis.transform.localRotation;
            FaceForward("KrakenKing eyes toward +Z", kingVis, tRoot, mats["L7_Eye"], 2f);
            if (throneVis != null && kingVis.transform.localRotation != before)
                throneVis.transform.localRotation = Quaternion.Euler(0f, 180f, 0f) * throneVis.transform.localRotation;
            LogBounds(kingVis, "KrakenKing");
        }
        if (throneVis != null) LogBounds(throneVis, "KrakenThrone");
        th.hurtboxes = new Collider[] { AddCapsule(th.pivot, "Hurtbox", new Vector3(0f, 0f, 0f), 12.5f, 76f) };
        th.flash = tRoot.gameObject.AddComponent<HitFlash>();
        th.islandData = tRoot.gameObject.AddComponent<IslandData>();
        th.islandData.radius = cfg.ThroneRadius;
        var shield = GameObject.CreatePrimitive(PrimitiveType.Sphere);
        shield.name = "Shield";
        Object.DestroyImmediate(shield.GetComponent<Collider>());
        shield.transform.SetParent(tRoot, false);
        shield.transform.localPosition = new Vector3(0f, 4f, 0f);
        shield.transform.localScale = Vector3.one * (cfg.ThroneRadius + 4f) * 2f;
        var shMr = shield.GetComponent<MeshRenderer>();
        shMr.sharedMaterial = mats["L7_Shield"];
        shMr.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
        th.shield = shMr;
        shield.SetActive(false);
        // two smaller rock-throwing tentacles beside the throne (throne-local, front corners)
        const float ThrowerScale = 0.42f;
        var throwers = new List<TentacleAttacker>();
        for (int s = -1; s <= 1; s += 2)
        {
            var tpos = new Vector3(s * (cfg.ThroneRadius + 2.5f), 0f, 3f);
            var ta = BuildTentacle(s < 0 ? "ThrowerL" : "ThrowerR", tRoot, tpos, tentModel, tentCtrl, tentMeta, mats, reach, yawFix, ThrowerScale);
            if (ta.animator != null) ta.animator.cullingMode = AnimatorCullingMode.AlwaysAnimate;
            throwers.Add(ta);
        }
        th.throwers = throwers.ToArray();
        ctrl.throne = th;

        // --- dolphin -------------------------------------------------------------
        string dolPath = KrakenDir + "Dolphin.fbx";
        var dolModel = AssetDatabase.LoadAssetAtPath<GameObject>(dolPath);
        var dRoot = NewChild(root.transform, "Dolphin", new Vector3(-14f, 0f, -30f));
        var dol = dRoot.gameObject.AddComponent<DolphinApplause>();
        dol.pivot = NewChild(dRoot, "Pivot", Vector3.zero);
        if (dolModel != null)
        {
            var vis = PlaceModel(dolModel, dol.pivot, Vector3.zero, Quaternion.identity, "Model", mats);
            dol.animator = vis.GetComponentInChildren<Animator>();
            if (dol.animator != null)
            {
                dol.animator.runtimeAnimatorController = CreateKrakenAnimator(dolPath, "Dolphin", "Jump");
                dol.animator.applyRootMotion = false;
                dol.animator.cullingMode = AnimatorCullingMode.AlwaysAnimate;
            }
            else Debug.LogError("[ShipButtlr] Dolphin.fbx has no Animator — check the Generic rig import.");
            var b = WorldBounds(vis);
            CheckOrientation("Dolphin upright", b.size.y > 3.5f && b.size.y > Mathf.Max(b.size.x, b.size.z) * 1.4f,
                             $"size={b.size} (expect height ≈ 4.2, the largest dimension)");
            FaceForward("Dolphin belly toward +Z", vis, dRoot, mats["L7_DolphinBelly"], 0.05f);
        }
        dol.pivot.localScale = Vector3.one * dol.modelScale;
        ctrl.dolphin = dol;

        Debug.Log("[ShipButtlr] Level 7 Kraken's Throne built.");
        return ctrl;
    }

    static TentacleAttacker BuildTentacle(string name, Transform parent, Vector3 localPos, GameObject model,
                                          AnimatorController ctrl, KrakenClipFile meta, Dictionary<string, Material> mats,
                                          float reach, float yawFix, float scale)
    {
        var t = NewChild(parent, name, localPos);
        var ta = t.gameObject.AddComponent<TentacleAttacker>();
        ta.pivot = NewChild(t, "Pivot", Vector3.zero);
        ta.pivot.localScale = Vector3.one * scale;
        ta.baseScale = scale;
        ta.reach = reach;
        if (model != null)
        {
            var vis = PlaceModel(model, ta.pivot, Vector3.zero, Quaternion.Euler(0f, yawFix, 0f), "Model", mats);
            ta.animator = vis.GetComponentInChildren<Animator>();
            if (ta.animator != null)
            {
                ta.animator.runtimeAnimatorController = ctrl;
                ta.animator.applyRootMotion = false;
                ta.animator.cullingMode = AnimatorCullingMode.CullUpdateTransforms;
            }
            ta.tip = FindDeep(vis.transform, meta != null && meta.meta != null && !string.IsNullOrEmpty(meta.meta.tipBone) ? meta.meta.tipBone : "T8");
            foreach (var r in vis.GetComponentsInChildren<Renderer>())
                r.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;   // 8 tall shadow casters are costly on mobile
        }
        string path = KrakenDir + "KrakenTentacle.fbx";
        var slam = KrakenClip(path, "Slam");
        var rec  = KrakenClip(path, "Recover");
        var thr  = KrakenClip(path, "Throw");
        if (slam != null) ta.slamImpactTime  = slam.length;
        if (rec  != null) ta.recoverDuration = rec.length;
        if (thr  != null) ta.throwDuration   = thr.length;
        if (meta != null && meta.meta != null && meta.meta.throwReleaseTime > 0f) ta.throwReleaseTime = meta.meta.throwReleaseTime;
        ta.sinkDepth = 40f;
        return ta;
    }

    // Samples the Slam clip on a temporary instance: checks the tip lands flat along +Z (turning the
    // model 180° if the axis conversion flipped it) and measures the real reach.
    static float MeasureTentacle(GameObject model, string fbxPath, Dictionary<string, Material> mats, ref float reach)
    {
        if (model == null) return 0f;
        var holder = new GameObject("TentacleProbe");
        var vis = PlaceModel(model, holder.transform, Vector3.zero, Quaternion.identity, "Model", mats);
        var tip = FindDeep(vis.transform, "T8");
        var slam = KrakenClip(fbxPath, "Slam");
        var idle = KrakenClip(fbxPath, "Idle");
        float yaw = 0f;
        if (tip == null || slam == null)
        {
            CheckOrientation("KrakenTentacle slam along +Z", false, tip == null ? "tip bone T8 missing" : "Slam clip missing");
            Object.DestroyImmediate(holder);
            return 0f;
        }
        if (idle != null)
        {
            idle.SampleAnimation(vis, 0f);
            Vector3 it = holder.transform.InverseTransformPoint(tip.position);
            CheckOrientation("KrakenTentacle upright at Idle", it.y > 25f, $"tip={it} (expect y ≈ 31)");
        }
        slam.SampleAnimation(vis, slam.length);
        Vector3 st = holder.transform.InverseTransformPoint(tip.position);
        if (st.z < 0f)
        {
            yaw = 180f;
            st = new Vector3(-st.x, st.y, -st.z);
        }
        reach = new Vector2(st.x, st.z).magnitude;
        CheckOrientation("KrakenTentacle slam lies flat along +Z", st.z > 25f && Mathf.Abs(st.y) < 3f,
                         $"tip at slam end={st} yawFix={yaw} reach={reach:F2}");
        Object.DestroyImmediate(holder);
        return yaw;
    }

    // -------------------------------------------------------------------------
    // HUD pieces (called from BuildGameScene)
    // -------------------------------------------------------------------------

    static CameraSplat BuildInkSplat(Transform hud)
    {
        var go = new GameObject("InkSplat");
        go.transform.SetParent(hud, false);
        var img = go.AddComponent<RawImage>();
        img.raycastTarget = false;
        img.enabled = false;
        var rt = go.GetComponent<RectTransform>();
        rt.anchorMin = Vector2.zero; rt.anchorMax = Vector2.one;
        rt.offsetMin = Vector2.zero; rt.offsetMax = Vector2.zero;
        var cs = go.AddComponent<CameraSplat>();
        cs.coverageTarget = 0.8f;
        cs.holdDuration   = 1f;
        cs.fadeDuration   = 0.5f;
        cs.coreColor      = new Color(0.05f, 0.03f, 0.09f);
        cs.rimColor       = new Color(0.13f, 0.08f, 0.22f);
        cs.streakColor    = new Color(0.24f, 0.10f, 0.34f);
        cs.gritColor      = new Color(0.01f, 0.01f, 0.02f);
        cs.glossStrength  = 0.3f;
        return cs;
    }

    static BossHUD BuildBossHUD(Transform hud)
    {
        var bar = CreateHPBar("BossHP", hud, "KRAKEN", BossHUD.KrakenColor,
                              new Vector2(0.5f, 1f), new Vector2(0.5f, 1f), new Vector2(0f, -112f), new Vector2(760f, 50f));
        var group = bar.transform.parent.gameObject;
        var rt = group.GetComponent<RectTransform>();
        rt.pivot = new Vector2(0.5f, 1f);
        rt.anchoredPosition = new Vector2(0f, -122f);   // objective text spans y -15…-85; the bar label sits above the bar
        var bh = group.AddComponent<BossHUD>();
        bh.bar = bar;
        bh.fill = bar.fillImage;
        bh.group = group.AddComponent<CanvasGroup>();
        bh.group.blocksRaycasts = false;
        bh.group.interactable = false;
        var label = group.transform.Find("Label")?.GetComponent<Text>();
        if (label != null) { label.fontSize = 22; label.fontStyle = FontStyle.Bold; label.alignment = TextAnchor.LowerLeft; }
        bh.nameText = label;
        var phaseGO = MakeText("Phase", group.transform, "PHASE 1 / 2", 20, new Color(1f, 0.85f, 0.85f));
        var prt = phaseGO.GetComponent<RectTransform>();
        prt.anchorMin = new Vector2(0f, 1f); prt.anchorMax = new Vector2(1f, 1f);
        prt.pivot = new Vector2(1f, 0f);
        prt.anchoredPosition = new Vector2(0f, 2f);
        prt.sizeDelta = new Vector2(0f, 24f);
        var ptxt = phaseGO.GetComponent<Text>();
        ptxt.alignment = TextAnchor.LowerRight;
        ptxt.raycastTarget = false;
        bh.phaseText = ptxt;
        foreach (var g in group.GetComponentsInChildren<Graphic>()) g.raycastTarget = false;
        group.SetActive(false);
        return bh;
    }
}
